const attention=(a:Account)=>a.alerts.length>0||!!a.error||!!a.data?.Error;const groups=useMemo(()=>Array.from(new Set(state.accounts.map(a=>a.group).filter(Boolean) as string[])).sort(),[state.accounts]);const scoped=useMemo(()=>state.accounts.filter(a=>(platformFilter==='all'||(a.platform||'commandcode')===platformFilter)&&(groupFilter==='all'||(groupFilter==='__none'?!a.group:a.group===groupFilter))),[state.accounts,platformFilter,groupFilter]);const filtered=useMemo(()=>scoped.filter(a=>`${a.name} ${a.data?.UserName||''} ${a.data?.Email} ${a.plan} ${a.group||''}`.toLowerCase().includes(search.toLowerCase())),[scoped,search]);const pages=Math.max(1,Math.ceil(filtered.length/capacity));const safePage=Math.min(page,pages-1);const visible=filtered.slice(safePage*capacity,(safePage+1)*capacity);const known=scoped.filter(a=>num(a.data?.Remaining)&&!a.error&&!a.data?.Error);const quotaAccounts=scoped.filter(a=>a.data?.UsageUnit==='percent'&&num(a.data?.MonthlyUsed)&&!a.error&&!a.data?.Error);const singleQuota=!known.length&&quotaAccounts.length===1?quotaAccounts[0].data!.MonthlyUsed!:null;const cnyKnown=known.filter(a=>a.data?.UsageUnit==='cny');const otherKnown=known.filter(a=>a.data?.UsageUnit!=='cny');const cnyBalance=cnyKnown.reduce((sum,a)=>sum+a.data!.Remaining!,0);const otherBalance=otherKnown.reduce((sum,a)=>sum+a.data!.Remaining!,0);const forecast=tokenForecast(scoped);const monthly=state.accounts.filter(a=>num(a.data?.MonthlyUsed)&&!a.error&&!a.data?.Error);const used=monthly.reduce((sum,a)=>sum+a.data!.MonthlyUsed!,0);const tokenAccounts=scoped.filter(a=>num(a.data?.TotalTokens)).filter((a,i,all)=>a.platform!=='opencode'||all.findIndex(b=>b.platform==='opencode'&&b.providerId===a.providerId)===i);const tokenTotal=tokenAccounts.reduce((n,a)=>n+a.data!.TotalTokens!,0);const tokenIn=tokenAccounts.reduce((n,a)=>n+(a.data!.InputTokens||0),0);const tokenOut=tokenAccounts.reduce((n,a)=>n+(a.data!.OutputTokens||0),0);const warnings=scoped.filter(attention).length;const last=state.accounts.map(a=>time(a.data?.FetchedAt)?.getTime()||0).sort((a,b)=>b-a)[0];
async function act(op:string,payload:unknown={}){try{const result=await request(op,payload);if(result.message)setToast(result.message);return result}catch(e){setToast((e as Error).message);throw e}}
useLayoutEffect(()=>{const node=tableRef.current;if(!node)return;const measure=()=>setCardCapacity(Math.max(2,Math.floor((node.clientHeight-10)/334)*2));const observer=new ResizeObserver(measure);observer.observe(node);measure();return()=>observer.disconnect()},[viewMode]);
function closeAccountModal(){if(proxyBusy||renameBusy||transferWorking||renewalSaving||(working&&!['login','replaceLogin'].includes(addOperation||'')))return;if(working){addPending.current=false;request('cancelLogin').catch(()=>{});setWorking(false);setAddOperation(null);setAddProgress('')}setModal(null);setError('');setToast('');setKey('');setTransferPassword('');setTransferConfirm('')}
useEffect(()=>{const t=time(selected?.renewalAt);setRenewalDate(t?new Date(t.getTime()+8*3600000).toISOString().slice(0,19):'')},[selected?.id]);
function openAdd(){setModal('add');setError('');setName('');setKey('');setMethod('password');setPlatform('commandcode');setUsageView('time');setModelPage(0)}
