async function replaceCredential(operation:'replace'|'replaceLogin'){const account=selected;if(!account||addPending.current)return;addPending.current=true;setWorking(true);setAddOperation(operation);setAddProgress(operation==='replaceLogin'?'等待官方登录授权…':'正在验证新凭据…');setError('');try{const reply=await request(operation==='replaceLogin'?'replaceLogin':'replaceCredential',{accountId:account.id,key});setKey('');setError('');setModal('detail');setToast(reply.message||'凭据已更新，原账号和历史记录已保留')}catch(e){if(addPending.current)setError((e as Error).message)}finally{addPending.current=false;setWorking(false);setAddOperation(null);setAddProgress('')}}
async function startOpenCodeOAuth(){if(addPending.current)return;if(!authMethod){setError('请先选择官方提供的授权方式；也可导入本机账号');return}addPending.current=true;setWorking(true);setAddOperation('login');setError('');setAddProgress('正在打开 OpenCode 官方授权…');try{const result=await request('openCodeOAuthBegin',{provider,methodId:authMethod,name,answer:Object.fromEntries(Object.entries(authAnswers).filter(([key])=>authFieldVisible(authMethods.find(m=>m.id===authMethod)?.form?.find(f=>f.key===key)||{key,type:'string'},authAnswers)))});setAuthMode(result.authMode||'auto');setAddProgress(result.instructions||'等待浏览器完成官方授权…');for(let i=0;i<180&&addPending.current;i++){await new Promise(resolve=>setTimeout(resolve,2000));if(!addPending.current)return;const status=await request('openCodeOAuthStatus',{name});if(status.authStatus==='complete'){setModal(null);setToast(status.message||'OpenCode 账号已导入');return}if(['failed','expired'].includes(status.authStatus||''))throw new Error(status.instructions||'官方授权未完成，请重新尝试')}if(addPending.current)throw new Error('官方授权等待超时，请重新尝试')}catch(error){if(addPending.current)setError((error as Error).message);request('cancelLogin').catch(()=>{})}finally{addPending.current=false;setWorking(false);setAddOperation(null);setAuthMode('');setAddProgress('')}}
useEffect(()=>{if(modal!=='add'||platform!=='opencode'||!['openai','github-copilot'].includes(provider))return;let current=true;setAuthMethods([]);setAuthMethod('');request('openCodeAuthMethods',{provider}).then(reply=>{if(!current)return;const methods=(reply.authMethods||[]);setAuthMethods(methods);setAuthMethod(methods[0]?.id||'');setAuthAnswers(authDefaults(methods[0]));}).catch(error=>{if(current)setAuthMethods([])});return()=>{current=false}},[modal,platform,provider]);
